    38  /*!
    39   * Each layer in an XCF file is stored as a matrix of
    40   * 64-pixel by 64-pixel images. The GIMP has a sophisticated
    41   * method of handling very large images as well as implementing
    42   * parallel processing on a tile-by-tile basis. Here, though,
    43   * we just read them in en-masse and store them in a matrix.
    44   */
    45  typedef QVector<QVector<QImage> > Tiles;
    46
    47  class XCFImageFormat
    48  {
    49  public:
    50      XCFImageFormat();
    51      bool readXCF(QIODevice *device, QImage *image);
    52
    53  private:
    54      /*!
    55       * Each GIMP image is composed of one or more layers. A layer can
    56       * be one of any three basic types: RGB, grayscale or indexed. With an
    57       * optional alpha channel, there are six possible types altogether.
    58       *
    59       * Note: there is only ever one instance of this structure. The
    60       * layer info is discarded after it is merged into the final QImage.
    61       */
    62      class Layer
    63      {
    64      public:
    65          quint32 width;          //!< Width of the layer
    66          quint32 height;     //!< Height of the layer
    67          qint32 type;            //!< Type of the layer (GimpImageType)
    68          char *name;         //!< Name of the layer
    69          quint32 hierarchy_offset;   //!< File position of Tile hierarchy
    70          quint32 mask_offset;        //!< File position of mask image
    71
    72          uint nrows;         //!< Number of rows of tiles (y direction)
    73          uint ncols;         //!< Number of columns of tiles (x direction)
    74
    75          Tiles image_tiles;      //!< The basic image
    76          //! For Grayscale and Indexed images, the alpha channel is stored
    77          //! separately (in this data structure, anyway).
    78          Tiles alpha_tiles;
    79          Tiles mask_tiles;       //!< The layer mask (optional)
    80
    81          //! Additional information about a layer mask.
    82          struct {
    83              quint32 opacity;
    84              quint32 visible;
    85              quint32 show_masked;
    86              uchar red, green, blue;
    87              quint32 tattoo;
    88          } mask_channel;
    89
    90          bool active;            //!< Is this layer the active layer?
    91          quint32 opacity = 255;  //!< The opacity of the layer
    92          quint32 visible = 1;    //!< Is the layer visible?
    93          quint32 linked;     //!< Is this layer linked (geometrically)
    94          quint32 preserve_transparency; //!< Preserve alpha when drawing on layer?
    95          quint32 apply_mask = 9; //!< Apply the layer mask? Use 9 as "uninitilized". Spec says "If the property does not appear for a layer which has a layer mask, it defaults to true (1).
    96                                  //   Robust readers should force this to false if the layer has no layer mask.
    97          quint32 edit_mask;      //!< Is the layer mask the being edited?
    98          quint32 show_mask;      //!< Show the layer mask rather than the image?
    99          qint32 x_offset = 0;    //!< x offset of the layer relative to the image
   100          qint32 y_offset = 0;    //!< y offset of the layer relative to the image
   101          quint32 mode = 0;       //!< Combining mode of layer (LayerModeEffects)
   102          quint32 tattoo;     //!< (unique identifier?)
   103
   104          //! As each tile is read from the file, it is buffered here.
   105          uchar tile[TILE_WIDTH *TILE_HEIGHT *sizeof(QRgb)];
   106
   107          //! The data from tile buffer is copied to the Tile by this
   108          //! method.  Depending on the type of the tile (RGB, Grayscale,
   109          //! Indexed) and use (image or mask), the bytes in the buffer are
   110          //! copied in different ways.
   111          void (*assignBytes)(Layer &layer, uint i, uint j);
   112
   113          Layer(void) : name(nullptr) {}
   114          ~Layer(void)
   115          {
   116              delete[] name;
   117          }
   118
   119          Layer(const Layer &) = delete;
   120          Layer &operator=(const Layer &) = delete;
   121      };
