   123      /*!
   124       * The in-memory representation of the XCF Image. It contains a few
   125       * metadata items, but is mostly a container for the layer information.
   126       */
   127      class XCFImage
   128      {
   129      public:
   130          quint32 width;          //!< width of the XCF image
   131          quint32 height;     //!< height of the XCF image
   132          qint32 type;            //!< type of the XCF image (GimpImageBaseType)
   133
   134          quint8 compression;     //!< tile compression method (CompressionType)
   135          float x_resolution = -1;//!< x resolution in dots per inch
   136          float y_resolution = -1;//!< y resolution in dots per inch
   137          qint32 tattoo;          //!< (unique identifier?)
   138          quint32 unit;           //!< Units of The GIMP (inch, mm, pica, etc...)
   139          qint32 num_colors = 0;  //!< number of colors in an indexed image
   140          QVector<QRgb> palette;          //!< indexed image color palette
   141
   142          int num_layers;         //!< number of layers
   143          Layer layer;            //!< most recently read layer
   144
   145          bool initialized;       //!< Is the QImage initialized?
   146          QImage image;           //!< final QImage
   147
   148          XCFImage(void) : initialized(false) {}
   149      };
   150
   151      //! In layer DISSOLVE mode, a random number is chosen to compare to a
   152      //! pixel's alpha. If the alpha is greater than the random number, the
   153      //! pixel is drawn. This table merely contains the random number seeds
   154      //! for each ROW of an image. Therefore, the random numbers chosen
   155      //! are consistent from run to run.
   156      static int random_table[RANDOM_TABLE_SIZE];
   157      static bool random_table_initialized;
   158
   159      //! This table is used as a shared grayscale ramp to be set on grayscale
   160      //! images. This is because Qt does not differentiate between indexed and
   161      //! grayscale images.
   162      static QVector<QRgb> grayTable;
   163
   164      //! This table provides the add_pixel saturation values (i.e. 250 + 250 = 255).
   165      //static int add_lut[256][256]; - this is so lame waste of 256k of memory
   166      static int add_lut(int, int);
   167
   168      //! The bottom-most layer is copied into the final QImage by this
   169      //! routine.
   170      typedef void (*PixelCopyOperation)(Layer &layer, uint i, uint j, int k, int l,
   171                                         QImage &image, int m, int n);
   172
   173      //! Higher layers are merged into the final QImage by this routine.
   174      typedef void (*PixelMergeOperation)(Layer &layer, uint i, uint j, int k, int l,
   175                                          QImage &image, int m, int n);
   176
   177      //! Layer mode static data.
   178      typedef struct {
   179          bool affect_alpha;      //!< Does this mode affect the source alpha?
   180      } LayerModes;
   181
   182      //! Array of layer mode structures for the modes described by
   183      //! LayerModeEffects.
   184      static const LayerModes layer_modes[];
