   186      bool loadImageProperties(QDataStream &xcf_io, XCFImage &image);
   187      bool loadProperty(QDataStream &xcf_io, PropType &type, QByteArray &bytes, quint32 &rawType);
   188      bool loadLayer(QDataStream &xcf_io, XCFImage &xcf_image);
   189      bool loadLayerProperties(QDataStream &xcf_io, Layer &layer);
   190      bool composeTiles(XCFImage &xcf_image);
   191      void setGrayPalette(QImage &image);
