   203      static void copyLayerToImage(XCFImage &xcf_image);
   204      static void copyRGBToRGB(Layer &layer, uint i, uint j, int k, int l,
   205                               QImage &image, int m, int n);
   206      static void copyGrayToGray(Layer &layer, uint i, uint j, int k, int l,
   207                                 QImage &image, int m, int n);
   208      static void copyGrayToRGB(Layer &layer, uint i, uint j, int k, int l,
   209                                QImage &image, int m, int n);
   210      static void copyGrayAToRGB(Layer &layer, uint i, uint j, int k, int l,
   211                                 QImage &image, int m, int n);
   212      static void copyIndexedToIndexed(Layer &layer, uint i, uint j, int k, int l,
   213                                       QImage &image, int m, int n);
   214      static void copyIndexedAToIndexed(Layer &layer, uint i, uint j, int k, int l,
   215                                        QImage &image, int m, int n);
   216      static void copyIndexedAToRGB(Layer &layer, uint i, uint j, int k, int l,
   217                                    QImage &image, int m, int n);
   218
   219      static void mergeLayerIntoImage(XCFImage &xcf_image);
   220      static void mergeRGBToRGB(Layer &layer, uint i, uint j, int k, int l,
   221                                QImage &image, int m, int n);
   222      static void mergeGrayToGray(Layer &layer, uint i, uint j, int k, int l,
   223                                  QImage &image, int m, int n);
   224      static void mergeGrayAToGray(Layer &layer, uint i, uint j, int k, int l,
   225                                   QImage &image, int m, int n);
   226      static void mergeGrayToRGB(Layer &layer, uint i, uint j, int k, int l,
   227                                 QImage &image, int m, int n);
   228      static void mergeGrayAToRGB(Layer &layer, uint i, uint j, int k, int l,
   229                                  QImage &image, int m, int n);
   230      static void mergeIndexedToIndexed(Layer &layer, uint i, uint j, int k, int l,
   231                                        QImage &image, int m, int n);
   232      static void mergeIndexedAToIndexed(Layer &layer, uint i, uint j, int k, int l,
   233                                         QImage &image, int m, int n);
   234      static void mergeIndexedAToRGB(Layer &layer, uint i, uint j, int k, int l,
   235                                     QImage &image, int m, int n);
   236
   237      static void initializeRandomTable();
   238      static void dissolveRGBPixels(QImage &image, int x, int y);
   239      static void dissolveAlphaPixels(QImage &image, int x, int y);
   240  };
