   285  /*!
   286   * This initializes the tables used in the layer dissolving routines.
   287   */
   288  void XCFImageFormat::initializeRandomTable()
   289  {
   290      // From GIMP "paint_funcs.c" v1.2
   291      srand(RANDOM_SEED);
   292
   293      for (int i = 0; i < RANDOM_TABLE_SIZE; i++) {
   294          random_table[i] = rand();
   295      }
   296
   297      for (int i = 0; i < RANDOM_TABLE_SIZE; i++) {
   298          int tmp;
   299          int swap = i + rand() % (RANDOM_TABLE_SIZE - i);
   760          if (layer.type == GRAYA_GIMAGE || layer.type == INDEXEDA_GIMAGE) {
   761              layer.alpha_tiles[j].resize(layer.ncols);
   762          }
   763
   764          if (layer.mask_offset != 0) {
   765              layer.mask_tiles[j].resize(layer.ncols);
   766          }
   767      }
   768
   769      for (uint j = 0; j < layer.nrows; j++) {
   770          for (uint i = 0; i < layer.ncols; i++) {
   771
   772              uint tile_width = (i + 1) * TILE_WIDTH <= layer.width
   773                                ? TILE_WIDTH : layer.width - i * TILE_WIDTH;
   774
   775              uint tile_height = (j + 1) * TILE_HEIGHT <= layer.height
   776                                 ? TILE_HEIGHT : layer.height - j * TILE_HEIGHT;
   777
   778              // Try to create the most appropriate QImage (each GIMP layer
   779              // type is treated slightly differently)
   780
   781              switch (layer.type) {
   782              case RGB_GIMAGE:
   783                  layer.image_tiles[j][i] = QImage(tile_width, tile_height, QImage::Format_RGB32);
   784                  layer.image_tiles[j][i].setColorCount(0);
   785                  if (layer.image_tiles[j][i].isNull()) {
   786                      return false;
   787                  }
   788                  break;
   789
   790              case RGBA_GIMAGE:
   791                  layer.image_tiles[j][i] = QImage(tile_width, tile_height, QImage::Format_ARGB32);
   792                  layer.image_tiles[j][i].setColorCount(0);
   793                  if (layer.image_tiles[j][i].isNull()) {
   794                      return false;
   795                  }
   796                  break;
   797
   798              case GRAY_GIMAGE:
   799                  layer.image_tiles[j][i] = QImage(tile_width, tile_height, QImage::Format_Indexed8);
   800                  layer.image_tiles[j][i].setColorCount(256);
   801                  if (layer.image_tiles[j][i].isNull()) {
   802                      return false;
   803                  }
   804                  setGrayPalette(layer.image_tiles[j][i]);
   805                  break;
   806
   807              case GRAYA_GIMAGE:
   808                  layer.image_tiles[j][i] = QImage(tile_width, tile_height, QImage::Format_Indexed8);
   809                  layer.image_tiles[j][i].setColorCount(256);
   810                  if (layer.image_tiles[j][i].isNull()) {
   811                      return false;
   812                  }
   813                  setGrayPalette(layer.image_tiles[j][i]);
   814
   815                  layer.alpha_tiles[j][i] = QImage(tile_width, tile_height, QImage::Format_Indexed8);
   816                  layer.alpha_tiles[j][i].setColorCount(256);
   817                  if (layer.alpha_tiles[j][i].isNull()) {
   818                      return false;
   819                  }
   820                  setGrayPalette(layer.alpha_tiles[j][i]);
   821                  break;
   822
   823              case INDEXED_GIMAGE:
   824                  layer.image_tiles[j][i] = QImage(tile_width, tile_height, QImage::Format_Indexed8);
   825                  layer.image_tiles[j][i].setColorCount(xcf_image.num_colors);
   826                  if (layer.image_tiles[j][i].isNull()) {
   827                      return false;
   828                  }
   829                  setPalette(xcf_image, layer.image_tiles[j][i]);
   830                  break;
   831
   832              case INDEXEDA_GIMAGE:
   833                  layer.image_tiles[j][i] = QImage(tile_width, tile_height, QImage::Format_Indexed8);
   834                  layer.image_tiles[j][i].setColorCount(xcf_image.num_colors);
   835                  if (layer.image_tiles[j][i].isNull()) {
   836                      return false;
   837                  }
   838                  setPalette(xcf_image, layer.image_tiles[j][i]);
   839
   840                  layer.alpha_tiles[j][i] = QImage(tile_width, tile_height, QImage::Format_Indexed8);
   841                  layer.alpha_tiles[j][i].setColorCount(256);
   842                  if (layer.alpha_tiles[j][i].isNull()) {
   843                      return false;
   844                  }
   845                  setGrayPalette(layer.alpha_tiles[j][i]);
   846              }
   847
   848              if (layer.mask_offset != 0) {
   849                  layer.mask_tiles[j][i] = QImage(tile_width, tile_height, QImage::Format_Indexed8);
   850                  layer.mask_tiles[j][i].setColorCount(256);
   851                  if (layer.mask_tiles[j][i].isNull()) {
   852                      return false;
   853                  }
   854                  setGrayPalette(layer.mask_tiles[j][i]);
   855              }
   856          }
   857      }
   858      return true;
   859  }
