   861  /*!
   862   * Apply a grayscale palette to the QImage. Note that Qt does not distinguish
   863   * between grayscale and indexed images. A grayscale image is just
   864   * an indexed image with a 256-color, grayscale palette.
   865   * \param image image to set to a grayscale palette.
   866   */
   867  void XCFImageFormat::setGrayPalette(QImage &image)
   868  {
   869      if (grayTable.isEmpty()) {
   870          grayTable.resize(256);
   871
   872          for (int i = 0; i < 256; i++) {
   873              grayTable[i] = qRgb(i, i, i);
   874          }
   875      }
   876
   877      image.setColorTable(grayTable);
   878  }
   879
   880  /*!
   881   * Copy the indexed palette from the XCF image into the QImage.
   882   * \param xcf_image XCF image containing the palette read from the data stream.
   883   * \param image image to apply the palette to.
   884   */
   885  void XCFImageFormat::setPalette(XCFImage &xcf_image, QImage &image)
   886  {
   887      Q_ASSERT(xcf_image.num_colors == xcf_image.palette.size());
   888
   889      image.setColorTable(xcf_image.palette);
   890  }
