  1276  /*!
  1277   * An XCF file can contain an arbitrary number of properties associated
  1278   * with a channel. Note that this routine only reads mask channel properties.
  1279   * \param xcf_io the data stream connected to the XCF image.
  1280   * \param layer layer containing the mask channel to collect the properties.
  1281   * \return true if there were no I/O errors.
  1282   */
  1283  bool XCFImageFormat::loadChannelProperties(QDataStream &xcf_io, Layer &layer)
  1284  {
  1285      while (true) {
  1286          PropType type;
  1287          QByteArray bytes;
  1288          quint32 rawType;
  1289
  1290          if (!loadProperty(xcf_io, type, bytes, rawType)) {
  1291  //          qDebug() << "XCF: error loading channel properties";
  1292              return false;
  1293          }
  1294
  1295          QDataStream property(bytes);
  1296
  1297          switch (type) {
  1298          case PROP_END:
  1299              return true;
  1300
  1301          case PROP_OPACITY:
  1302              property >> layer.mask_channel.opacity;
  1303              break;
  1304
  1305          case PROP_VISIBLE:
  1306              property >> layer.mask_channel.visible;
  1307              break;
  1308
  1309          case PROP_SHOW_MASKED:
  1310              property >> layer.mask_channel.show_masked;
  1311              break;
  1312
  1313          case PROP_COLOR:
  1314              property >> layer.mask_channel.red >> layer.mask_channel.green
  1315                       >> layer.mask_channel.blue;
  1316              break;
  1317
  1318          case PROP_TATTOO:
  1319              property >> layer.mask_channel.tattoo;
  1320              break;
  1321
  1322          default:
  1323  //              qDebug() << "XCF: unimplemented channel property " << rawType
  1324  //                      << ", size " << bytes.size() << endl;
  1325              break;
  1326          }
  1327      }
  1328  }
