  1336  void XCFImageFormat::assignMaskBytes(Layer &layer, uint i, uint j)
  1337  {
  1338      QImage &image = layer.mask_tiles[j][i];
  1339      uchar *tile = layer.tile;
  1340      const int width = image.width();
  1341      const int height = image.height();
  1342      const int bytesPerLine = image.bytesPerLine();
  1343      uchar *bits = image.bits();
  1344
  1345      for (int y = 0; y < height; y++) {
  1346          uchar *dataPtr = bits + y * bytesPerLine;
  1347          for (int x = 0; x < width; x++) {
  1348              *dataPtr++ = tile[0];
  1349              tile += sizeof(QRgb);
  1350          }
  1351      }
  1352  }
