  1400          image = QImage(xcf_image.width, xcf_image.height, QImage::Format_ARGB32);
  1401          if (image.isNull()) {
  1402              return false;
  1403          }
  1404          image.fill(qRgba(255, 255, 255, 0));
  1405          break;
  1406
  1407      case GRAY_GIMAGE:
  1408          if (layer.opacity == OPAQUE_OPACITY) {
  1409              image = QImage(xcf_image.width, xcf_image.height, QImage::Format_Indexed8);
  1410              image.setColorCount(256);
  1411              if (image.isNull()) {
  1412                  return false;
  1413              }
  1414              setGrayPalette(image);
  1415              image.fill(255);
  1416              break;
  1417          } // else, fall through to 32-bit representation
  1418          Q_FALLTHROUGH();
  1419      case GRAYA_GIMAGE:
  1420          image = QImage(xcf_image.width, xcf_image.height, QImage::Format_ARGB32);
  1421          if (image.isNull()) {
  1422              return false;
  1423          }
  1424          image.fill(qRgba(255, 255, 255, 0));
  1425          break;
  1426
  1427      case INDEXED_GIMAGE:
