  1442              image.setColorCount(xcf_image.num_colors);
  1443              if (image.isNull()) {
  1444                  return false;
  1445              }
  1446              image.fill(0);
  1447              setPalette(xcf_image, image);
  1448          } else if (xcf_image.num_colors <= 256) {
  1449              image = QImage(xcf_image.width, xcf_image.height, QImage::Format_Indexed8);
  1450              image.setColorCount(xcf_image.num_colors);
  1451              if (image.isNull()) {
  1452                  return false;
  1453              }
  1454              image.fill(0);
  1455              setPalette(xcf_image, image);
  1456          }
