  1610  /*!
  1611   * Copy an RGB pixel from the layer to the RGB image. Straight-forward.
  1612   * The only thing this has to take account of is the opacity of the
  1613   * layer. Evidently, the GIMP exporter itself does not actually do this.
  1614   * \param layer source layer.
  1615   * \param i x tile index.
  1616   * \param j y tile index.
  1617   * \param k x pixel index of tile i,j.
  1618   * \param l y pixel index of tile i,j.
  1619   * \param image destination image.
  1620   * \param m x pixel of destination image.
  1621   * \param n y pixel of destination image.
  1622   */
  1623  void XCFImageFormat::copyRGBToRGB(Layer &layer, uint i, uint j, int k, int l,
  1624                                    QImage &image, int m, int n)
  1625  {
  1626      QRgb src = layer.image_tiles[j][i].pixel(k, l);
  1627      uchar src_a = layer.opacity;
  1628
  1629      if (layer.type == RGBA_GIMAGE) {
  1630          src_a = INT_MULT(src_a, qAlpha(src));
  1631      }
  1632
  1633      // Apply the mask (if any)
  1634
  1635      if (layer.apply_mask == 1 && layer.mask_tiles.size() > (int)j &&
  1636              layer.mask_tiles[j].size() > (int)i) {
  1637          src_a = INT_MULT(src_a, layer.mask_tiles[j][i].pixelIndex(k, l));
  1638      }
  1639
  1640      image.setPixel(m, n, qRgba(src, src_a));
  1641  }
