  1737   * \param image destination image.
  1738   * \param m x pixel of destination image.
  1739   * \param n y pixel of destination image.
  1740   */
  1741  void XCFImageFormat::copyIndexedAToIndexed(Layer &layer, uint i, uint j, int k, int l,
  1742          QImage &image, int m, int n)
  1743  {
  1744      uchar src = layer.image_tiles[j][i].pixelIndex(k, l);
  1745      uchar src_a = layer.alpha_tiles[j][i].pixelIndex(k, l);
  1746      src_a = INT_MULT(src_a, layer.opacity);
  1747
  1748      if (layer.apply_mask == 1 &&
  1749              layer.mask_tiles.size() > (int)j &&
  1750              layer.mask_tiles[j].size() > (int)i) {
  1751          src_a = INT_MULT(src_a, layer.mask_tiles[j][i].pixelIndex(k, l));
  1752      }
  1753
  1754      if (src_a > 127) {
  1755          src++;
  1756      } else {
  1757          src = 0;
  1758      }
  1759
  1760      image.setPixel(m, n, src);
  1761  }
  1762
  1763  /*!
  1764   * Copy an IndexedA pixel from the layer to an RGB image. Straight-forward.
  1765   * The only thing this has to take account of is the opacity of the
  1766   * layer. Evidently, the GIMP exporter itself does not actually do this.
  1767   * \param layer source layer.
  1768   * \param i x tile index.
  1769   * \param j y tile index.
  1770   * \param k x pixel index of tile i,j.
  1771   * \param l y pixel index of tile i,j.
  1772   * \param image destination image.
  1773   * \param m x pixel of destination image.
  1774   * \param n y pixel of destination image.
  1775   */
  1776  void XCFImageFormat::copyIndexedAToRGB(Layer &layer, uint i, uint j, int k, int l,
  1777                                         QImage &image, int m, int n)
  1778  {
  1779      QRgb src = layer.image_tiles[j][i].pixel(k, l);
  1780      uchar src_a = layer.alpha_tiles[j][i].pixelIndex(k, l);
  1781      src_a = INT_MULT(src_a, layer.opacity);
  1782
  1783      // Apply the mask (if any)
  1784      if (layer.apply_mask == 1 && layer.mask_tiles.size() > (int)j &&
  1785              layer.mask_tiles[j].size() > (int)i) {
  1786          src_a = INT_MULT(src_a, layer.mask_tiles[j][i].pixelIndex(k, l));
  1787      }
  1788
  1789      // This is what appears in the GIMP window
  1790      if (src_a <= 127) {
  1791          src_a = 0;
  1792      } else {
  1793          src_a = OPAQUE_OPACITY;
  1794      }
  1795
  1796      image.setPixel(m, n, qRgba(src, src_a));
  1797  }
